        questions = B.spread(listOf(
            // Identity, governance and monitoring: logging and monitoring
            B.q("sa-m5-1", "sa-monitoring", "Investigators need two years of records of who created, changed or deleted Azure resources, searchable with KQL next to the resource logs. What do you recommend?", listOf("A diagnostic setting on each subscription that sends the activity log to the Log Analytics workspace", "Rely on the activity log in the portal", "Turn on boot diagnostics", "Application Insights on the web app"), setOf(0), "The activity log records control-plane actions such as create, change and delete, but keeps them only for 90 days. A subscription diagnostic setting sends it to a workspace, where it is kept as long as you set and queried alongside other logs.",
                scenario = "Elderberry Bank's security team investigates incidents in the subscriptions behind its Android banking app. Last month the trail they needed was older than 90 days and had gone.",
                whyWrong = mapOf(
                    1 to "The portal shows only the last 90 days, which is exactly what failed last month.",
                    2 to "Boot diagnostics captures VM start-up screens, not who changed resources.",
                    3 to "Application Insights watches the app's requests, not changes to Azure resources.",
                ),
            ),
            B.q("sa-m5-2", "sa-monitoring", "The team must be alerted when its own production database becomes unavailable, whether the cause is an Azure platform problem or something else, and told when it recovers. What do you recommend?", listOf("A Resource Health alert on the database", "A Service Health alert on the region", "A budget alert", "An Azure Advisor recommendation"), setOf(0), "Resource Health reports the health of your individual resources, such as one database, and why it is unavailable. A Resource Health alert fires when that resource's health changes, including when it recovers.",
