            B.q("sa-m5-32", "sa-backup-dr", "SAP HANA databases on Azure VMs need application-consistent backups with log backups, managed from Azure, without a third-party tool. What do you recommend?", listOf("Azure Backup for SAP HANA in Azure VMs, to a Recovery Services vault", "A daily VM snapshot only", "Copy the data files to Blob Storage", "Azure Site Recovery"), setOf(0), "Azure Backup integrates with SAP HANA through its certified Backint interface. It takes full, differential and log backups into a Recovery Services vault and restores to a point in time.",
                scenario = "Hartley Steel's SAP HANA system, which feeds stock levels to its Android sales app, moved to Azure VMs. The old backup tool's licence ends next month.",
                whyWrong = mapOf(
                    1 to "A VM snapshot alone is not application-consistent for HANA and has no log backups.",
                    2 to "Copying data files of a running database does not give a consistent backup.",
                    3 to "Site Recovery replicates for DR; it keeps no backup history.",
