            ),
            B.q("sa-m5-33", "sa-backup-dr", "The AKS-hosted API is stateless, and its data lives in a geo-replicated database. How should it be recovered in another region with the least standing cost?", listOf("Redeploy the cluster and workloads in the second region from infrastructure as code and GitOps when needed", "Back up the node VMs daily", "Keep a full-size cluster running idle in the second region", "Restore the cluster from a support ticket"), setOf(0), "For stateless workloads, the code and configuration are the recovery source. Bicep or Terraform recreates the cluster, and GitOps redeploys the workloads, while the data comes from the replicated database. Nothing runs until needed.",
                scenario = "Calloway Cinemas' Android booking API runs on AKS and keeps no state in the cluster. Its RTO is four hours, and the budget for idle DR resources is small.",
                whyWrong = mapOf(
                    1 to "Node VMs are disposable; backing them up does not recover the workloads.",
                    2 to "A full idle cluster gives a faster recovery than needed at a high standing cost.",
                    3 to "Microsoft support does not rebuild your cluster.",
                ),
            ),
            B.q("sa-m5-34", "sa-backup-dr", "A whole Azure file share was deleted by mistake an hour ago. What should have been enabled so it can be undeleted?", listOf("Soft delete for file shares", "Blob versioning", "A CanNotDelete lock on a resource group in another subscription", "Geo-redundant storage"), setOf(0), "Soft delete for Azure file shares keeps a deleted share, with its snapshots, for a retention period. Within that period it can be undeleted.",
                scenario = "An administrator at Dunstan Print deleted the share that holds artwork for its Android print-ordering app while cleaning up test shares.",
                whyWrong = mapOf(
                    1 to "Versioning is a Blob Storage feature, not Azure Files.",
                    2 to "A lock elsewhere does nothing for this share.",
                    3 to "Geo-redundancy copies the deletion too.",
                ),
            ),
            B.q("sa-m5-35", "sa-backup-dr", "A user needs one configuration file back from last Tuesday's backup of a Windows VM, without restoring the whole VM. What do you do?", listOf("Use file recovery from the VM's recovery point to mount it and copy the file", "Restore the whole VM and copy the file", "Fail over with Site Recovery", "Ask Microsoft support"), setOf(0), "Azure Backup's file recovery mounts a recovery point's disks as drives, so you can browse and copy individual files, then unmount. The VM is not restored.",
                scenario = "An engineer at Fairhaven Logistics overwrote the config file of the API behind its Android tracking app. The VM is backed up nightly by Azure Backup.",
                whyWrong = mapOf(
                    1 to "Restoring a whole VM for one file is slow and wasteful.",
                    2 to "Failover is for disasters, not single files.",
                    3 to "You can recover files yourself.",
                ),
            ),
            B.q("sa-m5-36", "sa-backup-dr", "The team must be told at once when any backup job fails across all vaults, through its existing action groups. What do you recommend?", listOf("Azure Monitor alerts for Azure Backup, routed to the action groups", "Check the portal every morning", "A budget alert", "A resource lock"), setOf(0), "Azure Backup raises built-in alerts in Azure Monitor, such as for failed jobs. Alert processing rules or alert rules route them to action groups, so the same channels notify the team.",
                scenario = "Elmhurst Housing found its backups for the Android repairs app had failed for nine days before anyone noticed.",
                whyWrong = mapOf(
                    1 to "Daily manual checks are how nine days went by unnoticed.",
                    2 to "Budget alerts concern money, not job failures.",
                    3 to "Locks prevent deletion and send no alerts.",
                ),
