            B.q("sa-m5-39", "sa-high-availability", "An API on AKS must keep running if an entire Azure region fails. What do you recommend? Select two.", listOf("Run an AKS cluster in each of two regions", "Put Azure Front Door in front of both clusters with health probes", "Add more nodes to the existing cluster", "Use a single cluster with the Free tier"), setOf(0, 1), "A cluster in each region removes the single region as a point of failure. Front Door probes both and sends users only to healthy ones, so a regional outage just moves traffic.",
                scenario = "Wexford Bank's Android payments API runs on one AKS cluster. Its regulator now requires survival of a regional outage.",
                whyWrong = mapOf(
                    2 to "More nodes in one region still fail with the region.",
                    3 to "The Free tier has no SLA and is still one region.",
                ),
            ),
            B.q("sa-m5-40", "sa-high-availability", "A Hyperscale database must survive a data centre failure with fast automatic failover. What do you configure?", listOf("Zone redundancy with at least one high-availability replica", "Named replicas only", "Geo-restore", "A smaller compute size"), setOf(0), "Hyperscale high-availability replicas are ready copies of the compute that take over if the primary fails. With zone redundancy they sit in other availability zones, so a data centre failure is survived quickly.",
                scenario = "Aldwick Media's Hyperscale database for its Android news app runs with no replicas. A zone failure would take it offline.",
                whyWrong = mapOf(
                    1 to "Named replicas are for reads and are not automatic failover targets.",
                    2 to "Geo-restore takes much longer and loses recent data.",
                    3 to "Compute size has nothing to do with surviving a failure.",
                ),
            ),
            B.q("sa-m5-41", "sa-high-availability", "Two clustered VMs in different availability zones need one shared data disk that survives a zone failure. What do you recommend?", listOf("A zone-redundant (ZRS) managed disk, used as a shared disk", "A locally redundant Premium SSD", "A temporary disk on one VM", "Blob Storage mounted with BlobFuse"), setOf(0), "ZRS managed disks copy data across three availability zones. As a shared disk they can be attached to VMs in different zones, so a clustered app keeps its data when one zone fails.",
                scenario = "Westbury Steel runs a two-node failover cluster for the database behind its Android plant-monitoring app. Each node is in its own zone, and they need one shared disk.",
                whyWrong = mapOf(
                    1 to "An LRS disk lives in one zone and fails with it.",
                    2 to "Temporary disks lose data and cannot be shared.",
                    3 to "BlobFuse is not a block disk for a failover cluster.",
