            B.q("sa-m5-44", "sa-compute", "Batch-style pods on AKS can be interrupted and should run as cheaply as possible, while system pods stay on regular nodes. What do you recommend?", listOf("A separate user node pool of Spot VMs for the batch pods", "Run the system node pool on Spot VMs", "Use a bigger regular node pool", "Move to a single huge node"), setOf(0), "AKS supports Spot node pools as user pools. Interruptible workloads run there cheaply, using taints and tolerations, while system pods stay on a regular system pool, which cannot use Spot.",
                scenario = "Nightjar Analytics runs nightly report jobs for its Android dashboard app on AKS. They tolerate restarts, and the cluster bill is growing.",
                whyWrong = mapOf(
                    1 to "System node pools cannot use Spot VMs, and evicting them would break the cluster.",
                    2 to "A bigger regular pool costs more.",
                    3 to "One huge node is a single point of failure and still costs full price.",
                ),
            ),
            B.q("sa-m5-45", "sa-compute", "Six small, low-traffic web apps each run on their own App Service plan. How do you cut cost without changing the apps?", listOf("Host them together on one App Service plan sized for their combined load", "Move each to its own VM", "Move each to AKS", "Buy six larger plans"), setOf(0), "An App Service plan is the set of VMs you pay for, and several apps can share one plan. Putting small apps together means paying for one plan instead of six.",
                scenario = "Hollis Vets runs six small admin sites, including one for its Android booking app, each on its own Standard plan and mostly idle.",
                whyWrong = mapOf(
                    1 to "Six VMs cost more and add patching.",
                    2 to "AKS adds a cluster to run for six small sites.",
                    3 to "Larger plans cost more, not less.",
                ),
            ),
            B.q("sa-m5-46", "sa-compute", "Each night, 500 independent tasks each need several hours of CPU on VMs with licensed software installed, and the pool should grow and shrink automatically. What do you recommend?", listOf("Azure Batch with a custom image and an autoscale formula on the pool", "Azure Functions on the Consumption plan", "Azure Logic Apps", "A single large VM"), setOf(0), "Azure Batch schedules many independent tasks across a pool of VMs, which can use a custom image with your software and an autoscale formula. It suits long, CPU-heavy parallel work.",
                scenario = "Kestrel Actuarial runs risk models every night for the figures in its Android advisor app. Each model takes three hours of CPU.",
                whyWrong = mapOf(
                    1 to "The Consumption plan stops a function after 10 minutes at most.",
                    2 to "Logic Apps orchestrates workflows; it does not run hours of CPU work.",
                    3 to "One VM would take days to run 500 three-hour tasks.",
