            ),
            // Infrastructure: migrations
            B.q("sa-m5-52", "sa-migrations", "Before and after migrating a workload, the architects want to check its design against reliability, security, cost, operational excellence and performance best practice. What do you use?", listOf("An Azure Well-Architected Review assessment", "Azure Pricing Calculator", "Azure Data Box", "A resource lock"), setOf(0), "The Azure Well-Architected Framework sets out five pillars: reliability, security, cost optimisation, operational excellence and performance efficiency. The Well-Architected Review asks questions about a workload and gives recommendations for each pillar.",
                scenario = "Southfield Energy is moving the back end of its Android meter app to Azure and wants an independent check that the target design is sound.",
                whyWrong = mapOf(
                    1 to "The calculator prices resources; it does not review design.",
                    2 to "Data Box moves data offline.",
                    3 to "Locks prevent deletion; they review nothing.",
                ),
            ),
            B.q("sa-m5-53", "sa-migrations", "Two hundred Hyper-V VMs must be discovered and assessed for Azure, including performance data for right-sizing. What do you recommend?", listOf("Deploy the Azure Migrate appliance for Hyper-V and run an assessment", "Count the VMs by hand", "Azure Monitor VM insights", "Azure Resource Graph"), setOf(0), "The Azure Migrate appliance for Hyper-V discovers VMs and collects their configuration and performance data. Assessments then recommend Azure VM sizes and costs based on real use.",
                scenario = "Ellesmere Health runs Hyper-V in two data centres, including the back end of its Android patient app, and must plan the move to Azure.",
                whyWrong = mapOf(
                    1 to "Counting gives no performance data for sizing.",
                    2 to "VM insights watches Azure VMs and Arc servers, not a migration assessment.",
                    3 to "Resource Graph queries resources already in Azure.",
                ),
            ),
            B.q("sa-m5-54", "sa-migrations", "Three hundred terabytes must reach Azure over a slow link, and the office keeps changing files during the weeks of transfer. What approach do you recommend? Select two.", listOf("Seed the bulk of the data offline with Azure Data Box", "Copy the changes made since the seed online, for example with AzCopy, before cutover", "Copy everything online over the slow link", "Stop all work in the office for two months"), setOf(0, 1), "A common pattern is to seed the bulk offline with Data Box, which is shipped to and from the Azure data centre, then copy only the changes made since then over the network before cutting over.",
                scenario = "Morwenna Films has 300 TB of footage for its Android streaming app on a NAS. Its 100 Mbps link would take most of a year, and editors keep working.",
                whyWrong = mapOf(
                    2 to "At 100 Mbps, 300 TB takes most of a year online.",
                    3 to "Stopping work for months is not acceptable to the business.",
                ),
            ),
            B.q("sa-m5-55", "sa-migrations", "A MySQL database must move to Azure Database for MySQL flexible server with only minutes of downtime at cutover. What do you recommend?", listOf("An online migration with Azure Database Migration Service, which keeps syncing changes until cutover", "A mysqldump taken on Friday night and restored on Monday", "Azure Data Box", "Azure Site Recovery"), setOf(0), "An online migration copies the data, then keeps applying changes from the source until you cut over. Downtime is only the few minutes needed to stop writes and switch the app.",
                scenario = "Wheatley Groceries' Android ordering app takes orders all day, every day, from a MySQL database on-premises.",
                whyWrong = mapOf(
                    1 to "A weekend dump and restore means the app is down for the whole copy.",
                    2 to "Data Box ships files offline; it does not keep a database in sync.",
                    3 to "Site Recovery moves VMs, not the database into a managed service.",
                ),
            ),
            // Infrastructure: networks
            B.q("sa-m5-56", "sa-network-connectivity", "The company offers an API to business customers, who must reach it privately from their own VNets, without peering or exposing it to the internet. What do you recommend?", listOf("Put the API behind a Standard Load Balancer and publish it as a Private Link service; customers create private endpoints to it", "VNet peering with every customer", "A public IP with an IP allow list", "A site-to-site VPN to each customer"), setOf(0), "A Private Link service exposes your service, behind a Standard Load Balancer, to other tenants. Each customer creates a private endpoint in their own VNet, so traffic stays private with no peering or overlapping address problems.",
                scenario = "Lattimer Payments sells its payments API, the same one its Android app uses, to banks. Banks refuse to send payment traffic over the internet.",
                whyWrong = mapOf(
                    1 to "Peering with every customer opens whole networks to each other and clashes on address ranges.",
                    2 to "A public IP is still on the internet, which the banks refuse.",
                    3 to "A VPN per customer is a lot of gateways and still connects whole networks.",
                ),
            ),
            B.q("sa-m5-57", "sa-network-connectivity", "Web VMs must serve users on the internet, but no VM may have its own public IP address. What do you recommend?", listOf("An Application Gateway with a public front end, sending traffic to the VMs' private addresses", "A public IP on each VM with an NSG", "A NAT gateway for inbound traffic", "Azure Bastion"), setOf(0), "Placing an Application Gateway, or a public load balancer, in front means only it has a public address. It forwards requests to VMs on private addresses, and the VMs are never directly reachable.",
                scenario = "Hadley Opticians' booking site, linked from its Android app, runs on four VMs. The security team bans public IPs on VMs.",
                whyWrong = mapOf(
                    1 to "Public IPs on VMs are banned, NSG or not.",
                    2 to "A NAT gateway handles outbound traffic only; it does not accept inbound requests.",
                    3 to "Bastion is for admin sessions, not public web traffic.",
                ),
            ),
            B.q("sa-m5-58", "sa-network-optimize", "VMs reach storage over a service endpoint. Security must stop data being copied out to storage accounts in other subscriptions over that same path. What do you add?", listOf("A service endpoint policy that allows only the approved storage accounts", "A route table", "Azure DNS", "A NAT gateway"), setOf(0), "Service endpoint policies filter traffic over a storage service endpoint, allowing only the storage accounts you list. Copying data to any other account over that path is blocked, which guards against data exfiltration.",
                scenario = "Bayard Pharma's analytics VMs for its Android trial app use a service endpoint to reach storage. An insider tried to copy data to a personal storage account.",
                whyWrong = mapOf(
                    1 to "Route tables steer traffic; they cannot tell one storage account from another.",
                    2 to "DNS resolves names and blocks nothing.",
                    3 to "A NAT gateway is for internet traffic, not service endpoints.",
                ),
            ),
            B.q("sa-m5-59", "sa-network-optimize", "Azure Front Door must reach an App Service origin privately, and the origin must refuse any traffic that does not come through Front Door's private connection. What do you recommend?", listOf("Front Door Premium with a Private Link origin to the App Service, and public access to the app disabled", "Front Door Standard with an IP allow list", "A public App Service with no restrictions", "Traffic Manager"), setOf(0), "Front Door Premium can connect to origins such as App Service through Private Link. With public access to the app disabled, only traffic arriving through Front Door's private connection reaches it.",
                scenario = "Crestline Bank's API for its Android app sits behind Front Door, but attackers have found the App Service's own address and bypass the WAF.",
                whyWrong = mapOf(
                    1 to "Standard does not support Private Link origins, and the app would still be public.",
                    2 to "An unrestricted app is exactly how attackers bypass the WAF.",
                    3 to "Traffic Manager is DNS routing with no private connection or WAF.",
                ),
            ),
            B.q("sa-m5-60", "sa-network-optimize", "Users in the EU must always be sent to the EU deployment, and users in the US to the US one, for data residency, not merely to the fastest. What do you recommend?", listOf("Traffic Manager with the geographic routing method", "Traffic Manager with the performance routing method", "Traffic Manager with weighted routing", "Azure Load Balancer"), setOf(0), "Geographic routing sends users to an endpoint based on where their DNS query comes from, so you can pin regions to deployments, such as the EU to the EU. Performance routing chooses the lowest latency instead.",
                scenario = "Ashdown Health's Android symptom-checker app runs separate deployments in the EU and the US. Lawyers insist EU users never reach the US deployment.",
                whyWrong = mapOf(
                    1 to "Performance routing picks the fastest endpoint, which could cross the border.",
                    2 to "Weighted routing splits traffic by percentages, regardless of location.",
                    3 to "A regional load balancer does not route by user location.",
                ),
            ),
